import json,numpy as np
from scipy.optimize import curve_fit
j=json.load(open('measurements.json'))
for exp in j['measurements'][1:]:
 print(exp['experiment'])
 for s in exp['samples']:
  T=np.array(s['temperature']); val=np.array(s.get('one_over_T1',s.get('resistivity'))); err=np.array(s['uncertainty'])
  if exp['experiment']=='NMR':
   val/=T;err/=T
   for limits in [(.25,1),(.5,1.5),(1,3),(.2,4)]:
    m=(T>=limits[0])&(T<=limits[1])&(val>2*err)
    if m.sum()<3:continue
    p,c=curve_fit(lambda x,a,b:a+b*x,1/T[m],np.log(val[m]),sigma=err[m]/val[m],absolute_sigma=True)
    print(s['filling'],limits,'Delta',-p[1],'+/-',np.sqrt(c[1,1]),'pref',np.exp(p[0]),'n',m.sum())
  else:
   m=val>0
   p,c=curve_fit(lambda x,a,b:a+b*x,1/T[m],np.log(val[m]),sigma=err[m]/val[m],absolute_sigma=True)
   print(s['filling'],'Arrhenius all',p,'sigma',np.sqrt(np.diag(c)))
   if np.any(~m):print('Tc bracket',T[~m][-1],T[m][0])
